public class Main {
    // 统计单词出现数量
    private static Map<String, Integer> countMp = new HashMap<>();
    // 单词内部转换策略
    private static Map<String, String> mp = new HashMap<>();
​
    // 自定义排序
    private static class CustomComparator implements Comparator<String> {
        @Override
        public int compare(String s1, String s2) {
            String sortedS1 = mp.get(s1);
            String sortedS2 = mp.get(s2);
​
            int count1 = countMp.get(sortedS1);
            int count2 = countMp.get(sortedS2);
​
            if (count1 != count2) return Integer.compare(count2, count1);
            if (s1.length() != s2.length()) return Integer.compare(s1.length(), s2.length());
            return sortedS1.compareTo(sortedS2);
        }
    }
​
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String s = scanner.nextLine();
        scanner.close();
​
        String[] words = s.split(" ");
        List<String> ans = new ArrayList<>(Arrays.asList(words));
​
        // 进行转换
        for (String word : ans) {
            char[] chars = word.toCharArray();
            Arrays.sort(chars);
            String sortedWord = new String(chars);
            mp.put(word, sortedWord);
            countMp.put(sortedWord, countMp.getOrDefault(sortedWord, 0) + 1);
        }
​
        // 排序
        ans.sort(new CustomComparator());
​
        // 输出
        for (String word : ans) {
            System.out.print(mp.get(word) + " ");
