// 通用 split 函数
function split(str, delimiter) {
  const result = [];
  let start = 0;
  let end = str.indexOf(delimiter);
  while (end !== -1) {
    result.push(str.substring(start, end));
    start = end + delimiter.length;
    end = str.indexOf(delimiter, start);
  }
  result.push(str.substring(start)); // 添加最后一个部分
  return result;
}
