// 统计单词出现数量
const countMp = new Map();
// 单词内部转换策略
const mp = new Map();
​
// 自定义排序
function cmp(s1, s2) {
  const first = mp.get(s1);
  const second = mp.get(s2);
  if (countMp.get(first) === countMp.get(second)) {
    if (s1.length === s2.length) {
      return first < second ? -1 : 1;
    }
    return s1.length < s2.length ? -1 : 1;
  }
  return countMp.get(first) > countMp.get(second) ? -1 : 1;
}
