  const ans = split(input, ' ');
​
  // 进行转换
  ans.forEach((word) => {
    const firstBack = word.split('').sort().join('');
    mp.set(word, firstBack);
    countMp.set(firstBack, (countMp.get(firstBack) || 0) + 1);
  });
​
  // 自定义排序
  ans.sort(cmp);
​
  // 输出结果
  const result = ans.map((word) => mp.get(word)).join(' ');
  console.log(result);
​
  rl.close();
});
